/*
 * Offline test of the GADV codec (src/Protocol/GadvCodec.cpp) against the shared protocol vectors
 * (docs/protocol-vectors.txt, generated by addon/tests/gen_protocol_vectors.py). Not part of the server build
 * (the module build compiles src/ only); built and run by tools\test-gadv-codec.ps1.
 *
 * Per vector: Encode(op, fields) == encoded; Decode(encoded) == op + fields; SplitIntoChunks(encoded, dir, id)
 * == chunks; ParseChunk on every chunk and concatenating the bodies gives encoded again.
 */

#include "../src/Protocol/GadvCodec.h"
#include <fstream>
#include <iostream>
#include <string>
#include <vector>

using namespace GuildAdventure::Gadv;

namespace
{
    struct Vector
    {
        std::string name;
        std::string op;
        std::vector<std::pair<std::string, std::string>> fields;
        std::string encoded;
        char direction = 0;
        uint32_t id = 0;
        std::vector<std::string> chunks;
    };

    // Values use C escapes \\ \n \r \t \0 and nothing else.
    std::string Unescape(std::string const& text)
    {
        std::string out;
        for (std::size_t i = 0; i < text.size(); ++i)
        {
            if (text[i] != '\\' || i + 1 >= text.size())
            {
                out += text[i];
                continue;
            }
            char const next = text[++i];
            switch (next)
            {
                case '\\': out += '\\'; break;
                case 'n':  out += '\n'; break;
                case 'r':  out += '\r'; break;
                case 't':  out += '\t'; break;
                case '0':  out += '\0'; break;
                default:   out += '\\'; out += next; break;
            }
        }
        return out;
    }

    std::vector<Vector> Load(std::string const& path)
    {
        std::ifstream file(path, std::ios::binary);
        std::vector<Vector> vectors;
        Vector current;
        bool open = false;
        std::string line;
        auto flush = [&]()
        {
            if (open)
                vectors.push_back(current);
            current = Vector();
            open = false;
        };

        while (std::getline(file, line))
        {
            if (!line.empty() && line.back() == '\r')
                line.pop_back();
            if (line.empty())
            {
                flush();
                continue;
            }
            if (line[0] == '#')
                continue;

            std::size_t const space = line.find(' ');
            std::string const keyword = line.substr(0, space);
            std::string const rest = space == std::string::npos ? std::string() : line.substr(space + 1);
            if (keyword == "vector")
            {
                flush();
                current.name = rest;
                open = true;
            }
            else if (keyword == "op")
                current.op = rest;
            else if (keyword == "field")
            {
                std::size_t const eq = rest.find('=');
                current.fields.emplace_back(rest.substr(0, eq), eq == std::string::npos ? std::string() : Unescape(rest.substr(eq + 1)));
            }
            else if (keyword == "encoded")
                current.encoded = rest;
            else if (keyword == "split")
            {
                current.direction = rest.empty() ? 0 : rest[0];
                current.id = uint32_t(std::stoul(rest.substr(2)));
            }
            else if (keyword == "chunk")
                current.chunks.push_back(rest);
        }
        flush();
        return vectors;
    }
}

int main(int argc, char** argv)
{
    if (argc < 2)
    {
        std::cerr << "usage: gadv_codec_test <protocol-vectors.txt>\n";
        return 2;
    }

    std::vector<Vector> const vectors = Load(argv[1]);
    if (vectors.empty())
    {
        std::cerr << "no vectors in " << argv[1] << "\n";
        return 2;
    }

    int failures = 0;
    int checks = 0;
    auto check = [&](bool ok, Vector const& vector, std::string const& what)
    {
        ++checks;
        if (!ok)
        {
            ++failures;
            std::cout << "FAIL " << vector.name << ": " << what << "\n";
        }
    };

    for (Vector const& vector : vectors)
    {
        Message message(vector.op);
        for (auto const& [key, value] : vector.fields)
            message.Set(key, value);

        if (!vector.encoded.empty() || vector.fields.empty())
            check(Encode(message) == vector.encoded, vector, "encode: got '" + Encode(message) + "'");

        if (!vector.encoded.empty())
        {
            std::optional<Message> decoded = Decode(vector.encoded);
            bool same = decoded && decoded->Opcode() == vector.op && decoded->Fields().size() == vector.fields.size();
            if (same)
                for (auto const& [key, value] : vector.fields)
                    if (decoded->GetString(key, "\x01missing") != value)
                        same = false;
            check(same, vector, "decode");
        }

        if (vector.direction)
        {
            std::vector<std::string> const chunks = SplitIntoChunks(vector.encoded, vector.direction, vector.id);
            check(chunks == vector.chunks, vector, "split: got " + std::to_string(chunks.size()) + " chunks, expected " +
                std::to_string(vector.chunks.size()));

            std::string joined;
            bool parsed = true;
            for (std::string const& text : vector.chunks)
            {
                std::optional<Chunk> chunk = ParseChunk(text);
                if (!chunk || chunk->direction != vector.direction || chunk->id != vector.id || chunk->total != vector.chunks.size())
                {
                    parsed = false;
                    break;
                }
                joined += chunk->body;
            }
            check(parsed && joined == vector.encoded, vector, "reassemble");

            for (std::string const& text : vector.chunks)
                check(text.size() <= MaxChunkBytes, vector, "chunk longer than " + std::to_string(MaxChunkBytes) + " bytes");
        }
    }

    // Malformed chunks are rejected (docs/protocol.md section 2).
    Vector const malformed{ "malformed chunks" };
    for (char const* text : { "X1,1,1:A", "C0,1,1:A", "C1,2,1:A", "C1,1,65:A", "C1,0,1:A", "C10000,1,1:A", "C1,1:A", "C1,1,1A" })
        check(!ParseChunk(text), malformed, std::string("accepted ") + text);

    std::cout << (failures ? "FAILED" : "OK") << ": " << (checks - failures) << "/" << checks << " checks passed, "
              << vectors.size() << " vectors\n";
    return failures ? 1 : 0;
}
